import sys
from collections import defaultdict

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    adj = defaultdict(set)

    for _ in range(m):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].add(v)
            adj[v].add(u)
        except StopIteration:
            break

    if n == 1:
        print("Yes")
        return

    def has_path(start_node, visited_count, mask):
        if visited_count == n:
            return True

        current = next(iter([i for i in range(1, n+1) if (mask >> (i-1)) & 1]))

        for neighbor in adj[current]:
            if not ((mask >> (neighbor-1)) & 1):
                new_mask = mask | (1 << (neighbor-1))
                if has_path(neighbor, visited_count + 1, new_mask):
                    return True
        return False

    found = False
    for start in range(1, n + 1):
        initial_mask = 1 << (start - 1)
        if has_path(start, 1, initial_mask):
